using Alterverse.AI;using Alterverse.CameraSystem;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;using Alterverse.UI;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Prototype
{
public sealed class PrototypeBootstrap:MonoBehaviour
{
[SerializeField]private bool buildOnStart=true;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(Object.FindAnyObjectByType<PrototypeBootstrap>()==null)new GameObject("AV_PrototypeBootstrap").AddComponent<PrototypeBootstrap>();}private void Start(){if(buildOnStart)BuildPrototype();}
public void BuildPrototype(){if(GameObject.Find("AV_Player")!=null)return;BuildArena();GameObject player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.name="AV_Player";player.transform.position=new Vector3(-32,1,-4);Destroy(player.GetComponent<CapsuleCollider>());CharacterController cc=player.AddComponent<CharacterController>();cc.height=2;cc.radius=.5f;HeroId selected=PlayerHeroSelection.Selected;HeroIdentity identity=player.AddComponent<HeroIdentity>();identity.Configure(selected);HeroCombatProfile profile=player.AddComponent<HeroCombatProfile>();profile.Configure(selected);HeroAbilityKit kit=player.AddComponent<HeroAbilityKit>();kit.Configure(selected);Health ph=player.AddComponent<Health>();ph.Configure(profile.Health);player.AddComponent<TeamMember>().Initialize(0);player.AddComponent<HeroMotor>();player.AddComponent<HeroRespawn>();player.AddComponent<BasicAttack>();PlayerHeroAbilities abilities=player.AddComponent<PlayerHeroAbilities>();SetColor(player,new Color(.055f,.035f,.09f));player.AddComponent<CombatFeedback>();if(selected==HeroId.Veyr)AddVeyrBlade(player.transform);SpawnHealingZone zeroZone=GameObject.Find("AV_ZeroSpawnZone")?.GetComponent<SpawnHealingZone>();if(zeroZone!=null){zeroZone.InitializeTeam(0);zeroZone.Initialize(ph);}SpawnHealingZone lumenZone=GameObject.Find("AV_LumenSpawnZone")?.GetComponent<SpawnHealingZone>();if(lumenZone!=null)lumenZone.InitializeTeam(1);UnityEngine.Camera cam=UnityEngine.Camera.main;if(cam==null){GameObject c=new("Main Camera");c.tag="MainCamera";cam=c.AddComponent<UnityEngine.Camera>();}cam.backgroundColor=new Color(.018f,.015f,.045f);MobaCamera mc=cam.GetComponent<MobaCamera>();if(mc==null)mc=cam.gameObject.AddComponent<MobaCamera>();mc.SetTarget(player.transform);new GameObject("AV_HUD").AddComponent<PrototypeHUD>().Initialize(ph,null,null);new GameObject("AV_LaneWaveSpawner").AddComponent<LaneWaveSpawner>();new GameObject("AV_5v5Roster").AddComponent<FiveVsFiveTestRoster>();new GameObject("AV_DimensionsFront").AddComponent<DimensionsFront>();new GameObject("AV_DimensionsFrontCombatBridge").AddComponent<DimensionsFrontCombatBridge>();new GameObject("AV_DimensionsFrontVisual").AddComponent<DimensionsFrontVisual>();new GameObject("AV_DimensionsFrontHUD").AddComponent<DimensionsFrontHUD>();new GameObject("AV_MatchTelemetry").AddComponent<MatchTelemetry>();new GameObject("AV_MatchScoreboard").AddComponent<MatchScoreboard>();new GameObject("AV_MatchOpening").AddComponent<MatchOpening>();}
private static void BuildArena(){Color zeroGround=new(.045f,.035f,.075f),lumenGround=new(.065f,.15f,.17f),lane=new(.16f,.105f,.22f);CreateGround("AV_DimensionZeroGround",new Vector3(-21,-.12f,0),new Vector3(42,.2f,72),zeroGround);CreateGround("AV_LumenGround",new Vector3(21,-.12f,0),new Vector3(42,.2f,72),lumenGround);CreateLane("AV_TopLane",16,lane);CreateLane("AV_MidLane",0,lane);CreateLane("AV_BotLane",-16,lane);CreateVisualBlock("AV_ZeroBasePad",new Vector3(-36,.04f,0),new Vector3(8,.05f,22),new Color(.11f,.04f,.17f),Vector3.zero);CreateVisualBlock("AV_LumenBasePad",new Vector3(36,.04f,0),new Vector3(8,.05f,22),new Color(.06f,.27f,.30f),Vector3.zero);CreateBaseCore(new Vector3(-36,1.15f,0),new Color(.52f,.08f,.76f),"AV_ZeroRealityCore");CreateBaseCore(new Vector3(36,1.15f,0),new Color(.08f,.72f,.78f),"AV_LumenRealityCore");CreateSpawnZone(new Vector3(-34,.07f,-4),new Color(.52f,.08f,.76f),"AV_ZeroSpawnZone");CreateSpawnZone(new Vector3(34,.07f,4),new Color(.08f,.72f,.78f),"AV_LumenSpawnZone");CreateTowers();for(int i=-15;i<=15;i++){float z=i*2.25f,x=Mathf.Sin(i*1.73f)*.65f;CreateVisualBlock("AV_RealityScar",new Vector3(x,.055f,z),new Vector3(.34f,.045f,1.85f),new Color(.48f,.07f,.72f),new Vector3(0,Mathf.Sin(i)*13,0));}for(int z=-28;z<=28;z+=8){CreateObelisk(new Vector3(-38,1.25f,z),new Color(.13f,.035f,.22f),false);CreateObelisk(new Vector3(38,1.25f,z),new Color(.055f,.31f,.35f),true);}for(int z=-24;z<=24;z+=12){CreateCrystal(new Vector3(-13,.65f,z),new Color(.42f,.07f,.68f));CreateCrystal(new Vector3(13,.65f,z),new Color(.06f,.62f,.70f));}CreateObjectiveZone(new Vector3(0,.07f,27),new Color(.16f,.55f,.78f),"AV_NorthObjective");CreateObjectiveZone(new Vector3(0,.07f,-27),new Color(.72f,.16f,.48f),"AV_SouthObjective");CreateRiftCore();}
private static void CreateSpawnZone(Vector3 p,Color c,string n){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(4.5f,.025f,4.5f);DisableCollider(g);SetColor(g,c);g.AddComponent<SpawnHealingZone>();}private static void CreateLane(string n,float z,Color c){CreateVisualBlock(n,new Vector3(0,.035f,z),new Vector3(72,.045f,2.4f),c,Vector3.zero);CreateVisualBlock(n+"_ZeroConnector",new Vector3(-30,.04f,z*.58f),new Vector3(15,.045f,1.6f),c,new Vector3(0,z>0?-22:z<0?22:0,0));CreateVisualBlock(n+"_LumenConnector",new Vector3(30,.04f,z*.58f),new Vector3(15,.045f,1.6f),c,new Vector3(0,z>0?22:z<0?-22:0,0));}private static void CreateTowers(){float[] lanes={16,0,-16};foreach(float z in lanes){CreateTower(new Vector3(-25,1.25f,z),0,new Color(.43f,.08f,.62f),"AV_ZeroTower");CreateTower(new Vector3(25,1.25f,z),1,new Color(.07f,.58f,.64f),"AV_LumenTower");}}private static void CreateTower(Vector3 p,int team,Color c,string n){GameObject t=GameObject.CreatePrimitive(PrimitiveType.Cylinder);t.name=n;t.transform.position=p;t.transform.localScale=new Vector3(.9f,1.25f,.9f);SetColor(t,c);Health h=t.AddComponent<Health>();h.Configure(260,true);t.AddComponent<LaneTower>().Initialize(team);CreateVisualCylinder(n+"_Base",new Vector3(p.x,.08f,p.z),new Vector3(1.25f,.03f,1.25f),c);}private static void CreateObjectiveZone(Vector3 p,Color c,string n){CreateVisualCylinder(n,p,new Vector3(2.5f,.025f,2.5f),c);for(int i=0;i<4;i++){float a=i*90*Mathf.Deg2Rad;CreateShard(p+new Vector3(Mathf.Cos(a)*2,.55f,Mathf.Sin(a)*2),c,.4f,true);}}private static void CreateBaseCore(Vector3 p,Color c,string n){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(1.4f,1.15f,1.4f);DisableCollider(g);SetColor(g,c);}private static void CreateRiftCore(){CreateVisualCylinder("AV_RiftOuter",new Vector3(0,.075f,0),new Vector3(3.25f,.035f,3.25f),new Color(.20f,.045f,.29f));CreateVisualCylinder("AV_RiftInner",new Vector3(0,.095f,0),new Vector3(2.35f,.045f,2.35f),new Color(.55f,.065f,.80f));CreateVisualCylinder("AV_RiftEye",new Vector3(0,.115f,0),new Vector3(1.15f,.05f,1.15f),new Color(.08f,.025f,.12f));GameObject core=GameObject.CreatePrimitive(PrimitiveType.Cube);core.name="AV_RiftCore";core.transform.position=new Vector3(0,1.45f,0);core.transform.localScale=Vector3.one*.72f;core.transform.rotation=Quaternion.Euler(25,45,20);DisableCollider(core);SetColor(core,new Color(.72f,.18f,1));core.AddComponent<RiftCoreVisual>();}private static void CreateGround(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;SetColor(g,c);}private static void CreateObelisk(Vector3 p,Color c,bool future){GameObject o=GameObject.CreatePrimitive(future?PrimitiveType.Cube:PrimitiveType.Cylinder);o.name=future?"AV_LumenStructure":"AV_ZeroObelisk";o.transform.position=p;o.transform.localScale=future?new Vector3(.65f,2.3f,.65f):new Vector3(.8f,1.8f,.8f);o.transform.rotation=Quaternion.Euler(0,future?45:0,future?8:0);DisableCollider(o);SetColor(o,c);}private static void CreateCrystal(Vector3 p,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="AV_RealityCrystal";g.transform.position=p;g.transform.localScale=new Vector3(.38f,1.25f,.38f);g.transform.rotation=Quaternion.Euler(18,45,18);DisableCollider(g);SetColor(g,c);g.AddComponent<MapAmbientVisual>();}private static void CreateShard(Vector3 p,Color c,float size,bool animated){GameObject s=GameObject.CreatePrimitive(PrimitiveType.Cube);s.name="AV_RiftShard";s.transform.position=p;s.transform.localScale=new Vector3(size*.35f,size,size*.35f);s.transform.rotation=Quaternion.Euler(20,45,25);DisableCollider(s);SetColor(s,c);if(animated)s.AddComponent<MapAmbientVisual>();}private static void CreateVisualCylinder(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=s;DisableCollider(g);SetColor(g,c);}private static void CreateVisualBlock(string n,Vector3 p,Vector3 s,Color c,Vector3 r){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;g.transform.rotation=Quaternion.Euler(r);DisableCollider(g);SetColor(g,c);}private static void AddVeyrBlade(Transform p)=>AddBlade(p,"Veyr_ShadowBlade",new Vector3(.55f,.15f,.15f),new Vector3(.12f,1.45f,.18f),new Color(.025f,.015f,.04f),-18);private static void AddBlade(Transform p,string n,Vector3 pos,Vector3 scale,Color c,float z){GameObject b=GameObject.CreatePrimitive(PrimitiveType.Cube);b.name=n;b.transform.SetParent(p,false);b.transform.localPosition=pos;b.transform.localRotation=Quaternion.Euler(8,0,z);b.transform.localScale=scale;DisableCollider(b);SetColor(b,c);}private static void DisableCollider(GameObject g){Collider c=g.GetComponent<Collider>();if(c!=null)c.enabled=false;}private static void SetColor(GameObject g,Color c){Renderer r=g.GetComponent<Renderer>();if(r!=null)r.material.color=c;}
}}
